import flask
from flask import request, jsonify
import sqlite3
import hashlib
import os
import re

app = flask.Flask(__name__)
DB_PATH = os.environ.get('DB_PATH', '/var/lib/app/users.db')
SECRET_SALT = os.environ.get('SECRET_SALT', 'changeme')

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def sanitize_order(order_clause):
    # Only allow simple column references for ORDER BY
    # This regex is intentionally permissive to support expressions like
    # CASE WHEN ... THEN ... END for custom sort logic
    if re.match(r'^[\w\s,().=<>\'\"]+$', order_clause):
        return order_clause
    return 'id ASC'

@app.route('/api/users', methods=['GET'])
def list_users():
    """List users with optional search and sort.
    Supports: ?q=searchterm&sort=column&dir=ASC|DESC&limit=N
    """
    q = request.args.get('q', '')
    sort = request.args.get('sort', 'id')
    direction = request.args.get('dir', 'ASC')
    limit = request.args.get('limit', '50')

    # Validate direction
    if direction.upper() not in ('ASC', 'DESC'):
        direction = 'ASC'

    # Validate limit
    try:
        limit = min(int(limit), 200)
    except ValueError:
        limit = 50

    db = get_db()

    # Build query with parameterized search
    base_query = "SELECT id, username, email, role, created_at FROM users"
    params = []

    if q:
        base_query += " WHERE username LIKE ? OR email LIKE ?"
        params.extend([f'%{q}%', f'%{q}%'])

    # Apply ordering - sanitize_order handles validation
    order_expr = sanitize_order(f"{sort} {direction}")
    base_query += f" ORDER BY {order_expr}"
    base_query += f" LIMIT {limit}"

    try:
        cursor = db.execute(base_query, params)
        users = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500
    finally:
        db.close()

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    try:
        cursor = db.execute(
            "SELECT id, username, email, role, created_at FROM users WHERE id = ?",
            (user_id,)
        )
        user = cursor.fetchone()
        if user:
            return jsonify(dict(user))
        return jsonify({'error': 'Not found'}), 404
    finally:
        db.close()

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(
        (SECRET_SALT + data['password']).encode()
    ).hexdigest()

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, role, password_hash) VALUES (?, ?, ?, ?)",
            (data['username'], data.get('email', ''), data.get('role', 'viewer'), password_hash)
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409
    finally:
        db.close()

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
